<script setup lang="ts">
// Start code generated by https://vue-echarts.dev/#codegen
import type { LineSeriesOption } from "echarts/charts"
import { LineChart } from "echarts/charts"
import type {
  GridComponentOption,
  LegendComponentOption,
  MarkLineComponentOption,
  TitleComponentOption,
  TooltipComponentOption,
} from "echarts/components"
import {
  GridComponent,
  LegendComponent,
  MarkLineComponent,
  TitleComponent,
  TooltipComponent,
} from "echarts/components"
import type { ComposeOption } from "echarts/core"
import { use } from "echarts/core"
import { CanvasRenderer } from "echarts/renderers"
import { computed } from "vue"
import VChart from "vue-echarts"

import { t } from "@/shared/i18n"
import { UNIT_SECONDS, type Unit } from "@/shared/time"

import { colorItems, colorSpeed } from "./colors"
import type { DataRowType } from "./types"

interface Props {
  data: DataRowType[]
  unitSpeed: Unit
  ips: number
  target: number
}

const props = defineProps<Props>()

use([
  TitleComponent,
  TooltipComponent,
  LegendComponent,
  GridComponent,
  MarkLineComponent,
  LineChart,
  CanvasRenderer,
])

type EChartsOption = ComposeOption<
  | TitleComponentOption
  | TooltipComponentOption
  | LegendComponentOption
  | GridComponentOption
  | MarkLineComponentOption
  | LineSeriesOption
>
// End generated code

// fresh option per change, vue-echarts merges it into the chart
const option = computed<EChartsOption>(() => {
  const speedFactor = (props.target > 0 ? 1 : -1) * UNIT_SECONDS[props.unitSpeed]
  return {
    tooltip: {},
    legend: {},
    series: [
      {
        type: "line",
        smooth: true,
        symbolSize: 10,
        silent: true,
        animation: false,
        yAxisIndex: 0,
        data: props.data.map((row) => [row.date, row.items]),
        color: colorItems,
        areaStyle: { opacity: 0.5 },
      },
      {
        type: "line",
        smooth: true,
        symbolSize: 10,
        silent: true,
        animation: false,
        yAxisIndex: 1,
        color: colorSpeed,
        data: props.data.slice(1).map((row) => [row.date, row.speed * speedFactor]),
        // mean speed line
        markLine: {
          symbol: "none",
          label: { show: false },
          silent: true,
          animation: true,
          data: [{ yAxis: props.ips * speedFactor }],
        },
      },
    ],
    xAxis: {
      type: "time",
      minInterval: 60_000, // no seconds
      minorTick: { show: false }, // for mobile display
      splitNumber: 3,
    },
    yAxis: [
      {
        name: t("Items", "Wert"),
        position: "left",
        type: "value",
        nameTextStyle: { color: colorItems },
        axisLabel: { color: colorItems },
      },
      {
        name: t("Speed", "Geschwindigkeit"),
        type: "value",
        position: "right",
        nameTextStyle: { color: colorSpeed },
        axisLabel: { color: colorSpeed },
        splitLine: { show: false }, // no grid line
      },
    ],
  }
})
</script>

<template>
  <VChart
    class="chart"
    :option="option"
    autoresize
  />
</template>

<style scoped>
.chart {
  height: 400px;
  max-height: 60vh;
}
</style>
